import{_ as a,o as t,c as i,al as s}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"Simulate Failsafes","description":"","frontmatter":{},"headers":[],"relativePath":"en/simulation/failsafes.md","filePath":"en/simulation/failsafes.md"}'),n={name:"en/simulation/failsafes.md"};function r(o,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="simulate-failsafes" tabindex="-1">Simulate Failsafes <a class="header-anchor" href="#simulate-failsafes" aria-label="Permalink to &quot;Simulate Failsafes&quot;">​</a></h1><p><a href="./../config/safety">Failsafes</a> define the safe limits/conditions under which you can safely use PX4, and the action that will be performed if a failsafe is triggered (for example, landing, holding position, or returning to a specified point).</p><p>In SITL some failsafes are disabled by default to enable easier simulation usage. This topic explains how you can test safety-critical behavior in SITL simulation before attempting it in the real world.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You can also test failsafes using <a href="./../simulation/hitl">HITL simulation</a>. HITL uses the normal configuration parameters of your flight controller.</p></div><h2 id="data-link-loss" tabindex="-1">Data Link Loss <a class="header-anchor" href="#data-link-loss" aria-label="Permalink to &quot;Data Link Loss&quot;">​</a></h2><p>The <em>Data Link Loss</em> failsafe (unavailability of external data via MAVLink) is enabled by default. This makes the simulation only usable with a connected GCS, SDK, or other MAVLink application.</p><p>Set the parameter <a href="./../advanced_config/parameter_reference#NAV_DLL_ACT">NAV_DLL_ACT</a> to the desired failsafe action to change the behavior. For example, set to <code>0</code> to disable it.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All parameters in SITL including this one get reset when you do <code>make clean</code>.</p></div><h2 id="rc-link-loss" tabindex="-1">RC Link Loss <a class="header-anchor" href="#rc-link-loss" aria-label="Permalink to &quot;RC Link Loss&quot;">​</a></h2><p>The <em>RC Link Loss</em> failsafe (unavailability of data from a remote control) is enabled by default. This makes the simulation only usable with either an active MAVLink or remote control connection.</p><p>Set the parameter <a href="./../advanced_config/parameter_reference#NAV_RCL_ACT">NAV_RCL_ACT</a> to the desired failsafe action to change the behavior. For example, set to <code>0</code> to disable it.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All parameters in SITL including this one get reset when you do <code>make clean</code>.</p></div><h2 id="low-battery" tabindex="-1">Low Battery <a class="header-anchor" href="#low-battery" aria-label="Permalink to &quot;Low Battery&quot;">​</a></h2><p>The simulated battery is implemented to never run out of energy, and by default only depletes to 50% of its capacity and hence reported voltage. This enables testing of battery indication in GCS UIs without triggering low battery reactions that might interrupt other testing.</p><p>To change this minimal battery percentage value use the parameter <a href="./../advanced_config/parameter_reference#SIM_BAT_MIN_PCT">SIM_BAT_MIN_PCT</a>.</p><p>To control how fast the battery depletes to the minimal value use the parameter <a href="./../advanced_config/parameter_reference#SIM_BAT_DRAIN">SIM_BAT_DRAIN</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>By changing <a href="./../advanced_config/parameter_reference#SIM_BAT_MIN_PCT">SIM_BAT_MIN_PCT</a> in flight, you can also test regaining capacity to simulate inaccurate battery state estimation or in-air charging technology.</p></div><p>The simulated battery can be completely disabled by setting <a href="./../advanced_config/parameter_reference#SIM_BAT_DRAIN">SIM_BAT_DRAIN</a> to 0. This is useful, for example, if you provide an external battery simulation via MAVLink.</p><h3 id="multiple-batteries" tabindex="-1">Multiple Batteries <a class="header-anchor" href="#multiple-batteries" aria-label="Permalink to &quot;Multiple Batteries&quot;">​</a></h3><p>By default only one battery is simulated. Additional batteries are simulated by enabling them like on a real vehicle: set the source of the battery to <code>Power Module</code> and configure it, e.g. <a href="./../advanced_config/parameter_reference#BAT2_SOURCE">BAT2_SOURCE</a> and <a href="./../advanced_config/parameter_reference#BAT2_N_CELLS">BAT2_N_CELLS</a> for a second battery. Each simulated battery is published as its own <code>battery_status</code> instance.</p><p>All batteries deplete according to <a href="./../advanced_config/parameter_reference#SIM_BAT_DRAIN">SIM_BAT_DRAIN</a> and <a href="./../advanced_config/parameter_reference#SIM_BAT_MIN_PCT">SIM_BAT_MIN_PCT</a> unless overridden for an individual battery with <a href="./../advanced_config/parameter_reference#SIM_BAT1_DRAIN">SIM_BATx_DRAIN</a> and <a href="./../advanced_config/parameter_reference#SIM_BAT1_MIN_PCT">SIM_BATx_MIN_PCT</a>. Setting <code>SIM_BATx_DRAIN</code> to a non-positive value uses the shared drain time. Setting <code>SIM_BATx_MIN_PCT</code> to a negative value uses the shared minimum charge. This can be used to test multi-battery behaviour, for example one battery depleting faster than the others.</p><h2 id="sensor-system-failure" tabindex="-1">Sensor/System Failure <a class="header-anchor" href="#sensor-system-failure" aria-label="Permalink to &quot;Sensor/System Failure&quot;">​</a></h2><p><a href="./../debug/failure_injection">Failure injection</a> can be used to simulate different types of failures in many sensors and systems. For example, this can be used to simulate absent or intermittent GPS, RC signal that has stopped or got stuck on a particular value, failure of the avoidance system, and much more.</p><p>Failure injection is gated by the <a href="./../advanced_config/parameter_reference#SYS_FAILURE_EN">SYS_FAILURE_EN</a> parameter.</p><p>For example, to simulate GPS failure, enter the following commands on the SITL instance <em>pxh shell</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Turn (all) GPS off (no position reported, as for a dead receiver)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Freeze (all) GPS on the last reported position (a &quot;stuck&quot; fix)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stuck</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Report a diverging position (offset by ~111 km, trips the GNSS redundancy checks)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrong</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restore normal GPS output</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ok</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To test the <a href="./../advanced_config/parameter_reference#COM_GNSSLOSS_ACT">GNSS redundancy failsafe</a> you can simulate a second GPS receiver: set the antenna-offset parameter <a href="./../advanced_config/parameter_reference#SENS_GPS1_OFFX">SENS_GPS1_OFFX</a> or <a href="./../advanced_config/parameter_reference#SENS_GPS1_OFFY">SENS_GPS1_OFFY</a> to a non-zero value, and the simulator publishes a second <code>sensor_gps</code> instance offset by that distance (in metres). You can then fail an individual receiver with the <code>-i</code> flag (<code>-i 0</code> = all instances, <code>-i 1</code> = first GPS, <code>-i 2</code> = second), for example <code>failure gps wrong -i 2</code>.</p></div>`,27)])])}const u=a(n,[["render",r]]);export{f as __pageData,u as default};
